import { api, db } from 'sdk';
import { sql } from 'sdk/db';
import { chatCounters } from '../schema.js';

export default async function (message) {
  if (typeof message?.text !== 'string') return;

  const chatId = message.chat.id;
  const [counter] = await db.insert(chatCounters)
    .values({ chatId, count: 1 })
    .onConflictDoUpdate({
      target: chatCounters.chatId,
      set: { count: sql`${chatCounters.count} + 1` },
    })
    .returning()
    .run();

  await api.sendMessage({
    chat_id: chatId,
    text: `Text messages in this chat: ${counter.count}`,
  });
}

