export const notes = table('notes', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  ownerId: integer('owner_id').notNull(),
  body: text('body').notNull(),
}, (t) => ({
  byOwner: index('notes_by_owner').on(t.ownerId),
}));

