import { db, EndpointError } from 'sdk';
import { eq, asc } from 'sdk/db';
import { notes } from '../schema.js';

export default async function (_input, ctx) {
  const ownerId = ctx?.initData?.user?.id;
  if (!Number.isSafeInteger(ownerId) || ownerId <= 0) {
    throw new EndpointError('Open this app in Telegram.', { code: 'UNAUTHORIZED' });
  }

  const rows = await db.select({ id: notes.id, body: notes.body })
    .from(notes)
    .where(eq(notes.ownerId, ownerId))
    .orderBy(asc(notes.id))
    .all();
  return { notes: rows };
}

