import { db, EndpointError } from 'sdk';
import { notes } from '../schema.js';

export default async function (input, ctx) {
  const ownerId = ctx?.initData?.user?.id;
  if (!Number.isSafeInteger(ownerId) || ownerId <= 0) {
    throw new EndpointError('Open this app in Telegram.', { code: 'UNAUTHORIZED' });
  }
  if (typeof input?.body !== 'string' || input.body.length > 2000) {
    throw new EndpointError('Enter a note of at most 2,000 characters.', {
      code: 'INVALID_NOTE',
    });
  }
  const body = input.body.trim();
  if (!body) {
    throw new EndpointError('A note cannot be empty.', { code: 'INVALID_NOTE' });
  }

  const [note] = await db.insert(notes)
    .values({ ownerId, body })
    .returning()
    .run();
  return { note: { id: note.id, body: note.body } };
}
